def rate_limit(calls, period):
    import time
    times = []
    def decorator(func):
        def wrapper(*args, **kwargs):
            now = time.time()
            times[:] = [t for t in times if now - t < period]
            if len(times) >= calls:
                raise Exception('Rate limit exceeded')
            times.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

