def overload(func):
    registry = {}
    def register(types):
        def decorator(f):
            registry[types] = f
            return f
        return decorator
    def dispatcher(*args):
        types = tuple(type(arg) for arg in args)
        if types in registry:
            return registry[types](*args)
        return func(*args)
    dispatcher.register = register
    return dispatcher

